%% time_average_moabs.m
%
% Purpose: apply a "dwell-window averaging" preprocessing step to the raw
% high-frequency data (10000 seconds) generated by MOABS. It simulates a real
% UAV that dwells at a sampling point for W steps (= W/Fs seconds) and
% averages the sensor readings over that period, yielding a cleaner
% "dwell measurement".
%
% Usage: edit the parameters in the CONFIG section below, then run the whole script.
%
% Note on the data layout (important; it is why a plain block average is
% enough, with no extra 3D reshape/permute needed):
%   The C matrix in the raw .mat file has shape (200000, 100). It is written such that
%   rows 100*(t-1)+1 to 100*t hold the full x=1..100 snapshot of the t-th
%   time step (t=1..6000), and the 100 columns within a row correspond to
%   y=1..100. In other words, 100 consecutive rows form "the complete 2D
%   concentration field at one instant"; time steps do not interleave and
%   no reordering is needed.
%   So for "time-window averaging" it is enough to accumulate these 6000
%   "100-row blocks" in groups of W and average them. The output keeps the
%   same "one block per 100 rows" format, only the total number of blocks
%   goes from 6000 to floor(6000/W).
%   The ws (wind speed) matrix has shape (600000, 300) and has the same
%   per-time-step block structure of 100 rows each (300 columns = 100 y
%   positions x 3 wind components), so the exact same block-averaging
%   logic is used.

clear; clc;

%% ===================== CONFIG section, edit as needed =====================
INPUT_DIR   = 'G=1_80_60_modified_Q_true_V7_eta_SNR_10_10000s_wind_and_quant_check';   % raw data directory
OUTPUT_DIR  = 'G=1_80_60_modified_Q_true_V7_eta_SNR_10_10000s_wind_and_quant_check/Fixed_Window/Time_avg_W200';  % output directory (created automatically)
HEIGHTS     = [5];   % height layers to process (correspond to Height-2/Height-5 in the file names)

Nt_raw      = 200000;     % number of raw time steps
Nx          = 100;
Ny          = 100;
Nws         = 3;        % number of wind-speed components u,v,w

WINDOW_SIZE = 200;       % <<< window length (in steps) being tested this time.
                        %     At a 20Hz sampling rate, 200 steps = 10 seconds.
                        %     200000/200 = 100 windows, for quick verification.

% Note on background concentration handling:
% In this batch of simulations plannerClass.bkg_ch4 was already set to 0
% during generation (see the comment "TODO: set the background
% concentration to 0 for now" in the planner), and the low-pass filter of
% filamentClass does not add any extra fixed background offset either, so
% this data itself contains no "background concentration constant" that
% needs to be subtracted. If you want to simulate a real sensor's non-zero
% background (e.g. the atmospheric background CH4), set SUBTRACT_BACKGROUND
% to true and specify BG_VALUE; the script will subtract this constant
% uniformly after averaging. If you only want to verify the denoising
% effect of the "window averaging" step itself, keep it false (the default).
SUBTRACT_BACKGROUND = false;
BG_VALUE            = 0.0;   % the unit must match the C matrix (kg/m^3)

%% ===================== Main processing =====================
if ~exist(OUTPUT_DIR, 'dir')
    mkdir(OUTPUT_DIR);
end

numWindows = floor(Nt_raw / WINDOW_SIZE);
fprintf('Raw time steps: %d, window length: %d steps (= %.2f s @ 20Hz), number of windows: %d\n', ...
    Nt_raw, WINDOW_SIZE, WINDOW_SIZE/20, numWindows);

if numWindows * WINDOW_SIZE < Nt_raw
    fprintf('Note: %d steps is not divisible by %d, the last %d steps will be discarded (less than one full window)\n', ...
        Nt_raw, WINDOW_SIZE, Nt_raw - numWindows*WINDOW_SIZE);
end

for h = HEIGHTS
    fprintf('\n===== Processing height layer Height-%d =====\n', h);

    % ---------- Concentration data ----------
    c_filename = sprintf('Plume-C-Data-Height-%d.mat', h);
    c_filepath = fullfile(INPUT_DIR, c_filename);
    fprintf('Reading: %s\n', c_filepath);
    data = load(c_filepath);
    C_raw = data.C;   % (600000, 100)

    if size(C_raw,1) ~= Nt_raw*Nx
        error('The number of rows of the C matrix (%d) does not match the expected value (%d), please check the Nt_raw/Nx settings', ...
            size(C_raw,1), Nt_raw*Nx);
    end

    [C_avg, raw_std_before, raw_std_after] = block_average(C_raw, Nt_raw, Nx, Ny, WINDOW_SIZE, numWindows);

    if SUBTRACT_BACKGROUND
        C_avg = C_avg - BG_VALUE;
    end

    fprintf('  Concentration data: raw per-step standard deviation (time dimension, single-point sampling) ~ %.4e\n', raw_std_before);
    fprintf('  Concentration data: standard deviation after window averaging (theoretically ~1/sqrt(W) times) ~ %.4e\n', raw_std_after);
    fprintf('  Actual reduction ratio: %.2fx (theoretical sqrt(%d)=%.2f)\n', ...
        raw_std_before/raw_std_after, WINDOW_SIZE, sqrt(WINDOW_SIZE));

    % ---------- Wind-speed data ----------
    ws_filename = sprintf('Plume-Wind-Data-Height-%d.mat', h);
    ws_filepath = fullfile(INPUT_DIR, ws_filename);
    fprintf('Reading: %s\n', ws_filepath);
    data_ws = load(ws_filepath);
    ws_raw = data_ws.ws;   % (600000, 300)

    if size(ws_raw,1) ~= Nt_raw*Nx
        error('The number of rows of the ws matrix (%d) does not match the expected value (%d)', size(ws_raw,1), Nt_raw*Nx);
    end

    ws_avg = block_average(ws_raw, Nt_raw, Nx, Ny*Nws, WINDOW_SIZE, numWindows);

    % ---------- Save ----------
    C = C_avg; %#ok<NASGU>
    out_c_path = fullfile(OUTPUT_DIR, c_filename);
    save(out_c_path, 'C', '-v7.3');
    fprintf('  Saved: %s (shape: %d x %d)\n', out_c_path, size(C_avg,1), size(C_avg,2));

    ws = ws_avg; %#ok<NASGU>
    out_ws_path = fullfile(OUTPUT_DIR, ws_filename);
    save(out_ws_path, 'ws', '-v7.3');
    fprintf('  Saved: %s (shape: %d x %d)\n', out_ws_path, size(ws_avg,1), size(ws_avg,2));
end

fprintf('\nAll done. New Nt = %d (was %d), remember to update accordingly\n', numWindows, Nt_raw);
fprintf('the Nt argument in loadLayerData() in test_srm.py on the Python side to %d.\n', numWindows);


%% ===================== Helper functions =====================
function [avg_mat, std_before, std_after] = block_average(raw_mat, Nt_raw, Nx, Ny_or_cols, W, numWindows)
    % raw_mat: raw matrix of shape (Nt_raw*Nx, Ny_or_cols), every Nx rows form one full time step
    % Returns: avg_mat of shape (numWindows*Nx, Ny_or_cols), where the W
    %       consecutive time steps within each window are averaged element-wise.

    n_cols = size(raw_mat, 2);
    avg_mat = zeros(numWindows * Nx, n_cols);

    % For diagnostics: take the time series at one fixed (x,y) position in
    % the middle of the matrix and look at how the standard deviation
    % changes before and after window averaging, to help judge the
    % denoising effect (for reference only, does not affect the main flow).
    probe_x = round(Nx/2);
    probe_y = round(n_cols/2);
    probe_series_raw = zeros(Nt_raw, 1);

    for w = 1:numWindows
        block_sum = zeros(Nx, n_cols);
        for t = 1:W
            t_global = (w-1)*W + t;
            row_start = (t_global-1)*Nx + 1;
            row_end   = t_global*Nx;
            this_block = raw_mat(row_start:row_end, :);
            block_sum = block_sum + this_block;
            probe_series_raw(t_global) = this_block(probe_x, probe_y);
        end
        out_row_start = (w-1)*Nx + 1;
        out_row_end   = w*Nx;
        avg_mat(out_row_start:out_row_end, :) = block_sum / W;
    end

    std_before = std(probe_series_raw);
    % The series at the same probe point after window averaging
    probe_series_avg = avg_mat(probe_x:Nx:end, probe_y);
    std_after = std(probe_series_avg);
end